import {migrate,finalize} from './strategy.js';
import {total,saved,available,cents,needs,allocate,reconcile} from './engine.js';
const KEY='jimu-wallet-v1', $=s=>document.querySelector(s), money=n=>'¥'+(n/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=migrate(JSON.parse(localStorage.getItem(KEY)))}catch{alert('本机记录无法读取，请勿清理浏览器数据。')}
const date=()=>new Date().toLocaleDateString('zh-CN');
function commit(n,type='计划更新',id=crypto.randomUUID()){
 const save=()=>{const disk=migrate(JSON.parse(localStorage.getItem(KEY)));if(JSON.stringify(disk)!==JSON.stringify(state))throw Error('另一个页面已更新数据，请刷新后重新操作');const next=finalize(state,n,{id,type});next.updated=date();localStorage.setItem(KEY,JSON.stringify(next));state=next;$('#modal').close();render();};
 const fail=e=>{const el=$('#error');if(el)el.textContent=e.message;else alert(e.message)};
 if(navigator.locks)navigator.locks.request('expona-save',save).catch(fail);else fail(Error('此浏览器不支持安全保存锁，请使用新版 Chrome 或 Edge'));
}
const field=(name,label,value='',type='number',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="0.01"':''} ${extra} required></label>`;
function modal(title,html,handler){$('#modal').innerHTML=`<form><h2>${title}</h2>${html}<p class="error" id="error" role="alert"></p><div class="actions"><button type="submit">继续</button><button type="button" class="secondary" id="cancel">取消</button></div></form>`;$('#cancel').onclick=()=>$('#modal').close();$('#modal form').onsubmit=e=>{e.preventDefault();try{handler(new FormData(e.target))}catch(err){$('#error').textContent=err.message}};$('#modal').showModal()}
function preview(title,html,n){const eventId=crypto.randomUUID();modal(title,html+'<p class="muted">确认后仅更新本机记录，不会实际转账。</p>',()=>commit(n,title,eventId));$('#modal button[type=submit]').textContent='确认并保存'}
function options(){return state.accounts.map((a,i)=>`<option value="${i}">${esc(a.name)}</option>`).join('')}
function initial(){return {accounts:[],goals:[],bills:[],templates:[],living:0,reserve:0,growth:0,free:0,monthly:0,payday:10,reserveTarget:0,freeTarget:0,updated:date(),checked:date()}}
function render(){if(!state){$('#app').innerHTML=`<header><div class="brand">Expona</div><span class="tag">本地原型 · V1</span></header><main class="intro"><span class="pill">让每一笔积累，都有方向</span><h1>从今天开始，<br>为未来多留一点。</h1><p class="muted">把收入变成有计划的储蓄。先照顾日常，再一点点接近你想要的未来。</p><div class="card"><h2>建立你的第一份储蓄计划</h2><p>添加账户与现有储蓄，设置生活预算。每次收入到账，由你确认新的分配建议。</p><div class="actions"><button id="start">开始设置 →</button><button id="demo" class="secondary">体验模拟数据</button></div></div><footer>数据只保存在当前浏览器。第一版无备份与同步，清理浏览器数据将丢失记录。所有金额均为人民币。</footer></main>`;$('#start').onclick=setup;$('#demo').onclick=()=>{const n=initial();Object.assign(n,{demo:true,accounts:[{name:'工资卡',balance:2300000},{name:'微信',balance:120000}],monthly:240000,payday:10,reserveTarget:1000000,reserve:800000,living:180000,free:40000,freeTarget:40000,growth:300000,goals:[{name:'学习基金',target:1000000,saved:500000,priority:1,due:''}]});commit(n)};return}
state=migrate(state);const gap=available(state), target=needs(state);$('#app').innerHTML=`<header><div class="brand">Expona <small style="font-size:12px">为未来积累</small></div><span class="tag">${state.demo?'模拟体验':'仅存本机'} · CNY</span></header><main><div class="actions" style="justify-content:space-between"><div><small>我的储蓄计划</small><h1>为未来，稳步积累。</h1></div><div class="actions"><button class="secondary" data-action="strategy">分配策略</button><button class="secondary" data-action="history">记录</button><button class="secondary" data-action="settings">计划设置</button></div></div>${state.demo?'<div class="warn">正在使用模拟数据。<button class="secondary" data-action="restart">开始我的计划</button></div>':''}<section class="hero"><small>储蓄余额 · 不含备用金</small><div class="amount">${money(saved(state))}</div><p>未来增长储备 ${money(state.growth)}</p><div class="actions"><button data-action="income">＋ 添加到账收入</button><button data-action="allocate">查看分配建议 →</button></div></section><section class="card stats"><div><small>备用金</small><strong>${money(state.reserve)}</strong></div><div><small>生活费预留</small><strong>${money(state.living)}</strong></div><div><small>自由支配</small><strong>${money(state.free)}</strong></div></section>${gap<0?`<div class="warn">待调整：余额比用途记录少 ${money(-gap)}。请核对差额并手动调整用途，未处理前暂停新分配。</div>`:''}${state.living<target?`<div class="warn">按当前预算，至下次固定收入前的生活费预留还差 ${money(target-state.living)}。查看分配建议或调整计划。</div>`:''}<div class="grid"><div><section class="card"><div class="row"><h2>储蓄目标</h2><button class="secondary" data-action="goal">＋ 目标</button></div>${state.goals.length?state.goals.map((g,i)=>`<div class="goal"><div class="row"><h3>${esc(g.name)}</h3><span class="pill">优先级 ${g.priority}</span></div><div class="progress"><span style="width:${Math.min(100,g.saved/g.target*100)}%"></span></div><div class="row"><span>${money(g.saved)} <small>/ ${money(g.target)}</small></span><button class="secondary" data-edit="${i}">编辑</button></div><small>${g.due?`${esc(g.due)} 前完成 · ${g.saved>=g.target?'已达成':`剩余 ${money(Math.max(0,g.target-g.saved))}，${new Date(g.due)<new Date()?'期限已到':'月均需存 '+money(Math.ceil(Math.max(0,g.target-g.saved)/Math.max(1,Math.ceil((new Date(g.due)-new Date())/86400000/30.44))))}；未计入未来未到账收入`}`:'无固定期限，按自己的节奏积累'}</small></div>`).join(''):'<p class="empty">添加第一个目标，给储蓄一个具体的方向。</p>'}<div class="row"><div><h3>未来增长储备</h3><small>没有固定终点，留给未来的可能</small></div><strong>${money(state.growth)}</strong></div><button class="secondary" data-action="adjust">手动调整资金用途</button></section></div><div><section class="card"><div class="row"><h2>我的账户</h2><button class="secondary" data-action="account">＋</button></div>${state.accounts.map(a=>`<div class="row"><span>${esc(a.name)}</span><strong>${money(a.balance)}</strong></div>`).join('')}<div class="row"><small>账户总余额</small><span>${money(total(state))}</span></div><div class="row"><small>${gap<0?'待处理缺口':'尚未分配'}</small><span>${money(Math.abs(gap))}</span></div><p><small>余额核对于 ${esc(state.checked)} · 建议每周更新</small></p><button class="secondary" data-action="check">核对账户余额</button></section><section class="card"><h2>这份计划如何分配？</h2><p class="muted">必要生活费 → 备用金 → 自由支配预留 → 优先储蓄目标 → 未来增长储备</p><small>月度生活预算 ${money(state.monthly)}，固定到账日每月 ${state.payday} 日。日常预算按每天所在月份天数折算，另加到期固定支出。</small><div class="row"><span>固定支出 ${state.bills.length} 项</span><button class="secondary" data-action="bill">管理</button></div></section></div></div><footer>本机保存 · 无备份与同步 · 最近保存 ${esc(state.updated)}。本原型不连接银行，不处理负债，不预测投资收益。</footer></main>`;
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actions[b.dataset.action]());document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>goal(Number(b.dataset.edit)))}
function setup(){modal('从现有资金开始',field('name','第一个账户名称','银行卡','text')+field('balance','当前余额（元）')+field('saved','其中已有储蓄（元）',0)+field('monthly','每月生活预算（不含单列固定支出）',0)+field('payday','固定收入到账日',10,'number','max="31" step="1"')+field('reserve','备用金目标（元）',0),f=>{const n=initial(),balance=cents(f.get('balance')),sv=cents(f.get('saved'));if(sv>balance)throw Error('已有储蓄不能超过余额');n.accounts=[{name:f.get('name').trim(),balance}];n.growth=sv;n.monthly=cents(f.get('monthly'));n.payday=day(f.get('payday'));n.reserveTarget=cents(f.get('reserve'));commit(n)})}
function day(v){const d=Number(v);if(!Number.isInteger(d)||d<1||d>31)throw Error('日期请填写 1–31 的整数');return d}
function goal(i){const g=state.goals[i]||{name:'',target:0,priority:state.goals.length+1,due:'',saved:0};modal(i===undefined?'添加储蓄目标':'编辑储蓄目标',field('name','目标名称',g.name,'text')+field('target','目标金额（元）',g.target/100)+field('priority','优先级（数字越小越优先）',g.priority,'number','step="1"')+`<label>期望完成日期（可选）<input name="due" type="date" value="${g.due}"></label>`,f=>{const n=structuredClone(state),target=cents(f.get('target')),priority=Number(f.get('priority'));if(target<=0||target<g.saved)throw Error('目标金额需大于零，且不能低于已存金额');if(!Number.isInteger(priority)||priority<1)throw Error('优先级需为正整数');const item={...g,id:g.id||crypto.randomUUID(),name:f.get('name').trim(),target,priority,due:f.get('due')};if(i===undefined)n.goals.push(item);else n.goals[i]=item;commit(n)})}
const actions={
strategy(){modal('动态分配策略',`<label>策略<select name="mode"><option value="priority" ${state.strategy.mode==='priority'?'selected':''}>优先级依次补足</option><option value="dynamic" ${state.strategy.mode==='dynamic'?'selected':''}>期限进度 + 剩余加权</option></select></label><p class="muted">动态策略先照顾必要预留，再按期限安排本月进度；剩余资金按目标优先级的倒数权重分配。没有收益预测，不会挪用已有储蓄。</p>`+field('limit','备用金每月补入上限（0 表示不限）',state.strategy.reserveLimit/100)+field('weight','未来增长储备权重（1–10000；优先级 1 的目标权重为 100）',state.strategy.growthWeight,'number','max="10000" step="1"'),f=>{const n=structuredClone(state),weight=Number(f.get('weight'));if(!Number.isInteger(weight)||weight<1||weight>10000)throw Error('权重需为 1–10000 的整数');n.strategy={mode:f.get('mode'),reserveLimit:cents(f.get('limit')),growthWeight:weight};preview('确认策略变更','<p>只改变后续分配建议，不自动移动现有资金。已用月度额度保留，下个月自然重新计数。</p>',n)})},
history(){modal('操作记录',state.ledger.length?[...state.ledger].reverse().map(e=>`<div class="row"><div><strong>${esc(e.type)}</strong><br><small>${esc(new Date(e.at).toLocaleString('zh-CN'))}</small>${e.allocation?.changes?e.allocation.changes.map(c=>`<p>${esc(c.label)} ＋${money(c.amount)}</p>`).join(''):''}<details><summary>余额与用途变动</summary><small>${['living','reserve','free','growth'].map((k,i)=>`${['生活费','备用金','自由支配','未来增长储备'][i]}：${money(e.before?.[k]??0)} → ${money(e.after?.[k]??0)}`).join('<br>')}<br>${(e.after?.goals??[]).map(g=>`${esc(g.name)}：${money(e.before?.goals.find(x=>x.id===g.id)?.saved??0)} → ${money(g.saved)}`).join('<br>')}<br>${(e.after?.accounts??[]).map((a,i)=>`${esc(a.name)}：${money(e.before?.accounts[i]?.balance??0)} → ${money(a.balance)}`).join('<br>')}</small></details></div></div>`).join(''):'<p>升级前的历史未记录；后续操作会保存流水。</p>',()=>$('#modal').close());$('#modal button[type=submit]').textContent='关闭'},

restart(){modal('开始使用真实数据','<p>确认后清除当前模拟数据，重新设置你的计划。</p>',()=>{localStorage.removeItem(KEY);state=null;$('#modal').close();render();setup()})},
goal:()=>goal(),
settings(){modal('计划设置',field('monthly','每月生活预算（不含固定支出）',state.monthly/100)+field('payday','固定收入到账日',state.payday,'number','max="31" step="1"')+field('reserve','备用金目标',state.reserveTarget/100)+field('free','自由支配预留目标',state.freeTarget/100),f=>{const n=structuredClone(state);n.monthly=cents(f.get('monthly'));n.payday=day(f.get('payday'));n.reserveTarget=cents(f.get('reserve'));n.freeTarget=cents(f.get('free'));commit(n)})},
account(){modal('添加资金账户',field('name','账户名称','','text')+field('balance','现有余额（不是新增收入）',0),f=>{const n=structuredClone(state);n.accounts.push({name:f.get('name').trim(),balance:cents(f.get('balance'))});preview('确认添加账户','<p>该余额加入总资金，暂未分配用途。已有储蓄可通过手动调整用途录入。</p>',n)})},
income(){modal('确认收入到账',`<label>收入模板<select id="template"><option value="">手动填写</option>${state.templates.map((t,i)=>`<option value="${i}">${esc(t.name)}</option>`).join('')}</select></label>`+field('name','收入名称','工资','text')+field('amount','到账金额（元）')+field('date','到账日期',new Date().toLocaleDateString('en-CA'),'date')+`<label>到账账户<select name="account">${options()}</select></label><label>类型<select name="kind"><option>固定收入</option><option>不定期收入</option></select></label><label><input style="display:inline;width:auto" name="template" type="checkbox"> 保存为模板（不会自动入账）</label>`,f=>{const n=structuredClone(state),amount=cents(f.get('amount'));if(amount<=0)throw Error('到账金额需大于零');if(f.get('date')>new Date().toLocaleDateString('en-CA'))throw Error('只能确认今天或之前已到账的收入');n.accounts[Number(f.get('account'))].balance+=amount;if(f.get('template'))n.templates.push({name:f.get('name'),amount,kind:f.get('kind')});const fingerprint=[f.get('name').trim(),f.get('date'),amount,f.get('account')].join('|');if(n.ledger.some(e=>e.type==='确认这笔钱已经到账'&&e.allocation?.incomeFingerprint===fingerprint))throw Error('相同名称、日期、金额和账户的收入已登记；若为另一笔，请修改名称加以区分');n.pendingAllocation={incomeFingerprint:fingerprint};n.lastIncome={name:f.get('name'),date:f.get('date'),amount};preview('确认这笔钱已经到账',`<p>${esc(f.get('name'))} · ${esc(f.get('date'))}</p><h2>＋ ${money(amount)}</h2><p>计入 ${esc(n.accounts[Number(f.get('account'))].name)}。请勿重复确认同一笔收入。保存后可查看分配建议。</p>`,n)});$('#template').onchange=e=>{const t=state.templates[e.target.value];if(t){$('#modal [name=name]').value=t.name;$('#modal [name=amount]').value=t.amount/100;$('#modal [name=kind]').value=t.kind}}},
allocate(){try{const p=allocate(state);preview('分配建议 · 等你确认',p.details.map(d=>`<p><strong>${esc(d.label)}</strong><br><small>${esc(d.reason)}。本轮需求 ${money(d.want)}，可分配 ${money(d.amount)}${d.amount<d.want?' · 资金不足':''}</small></p>`).join('')+p.changes.map(c=>`<div class="row"><span>${esc(c.label)}</span><strong>＋${money(c.amount)}</strong></div>`).join('')+(!p.changes.length?'<p>当前没有尚未分配的资金。</p>':'')+(p.shortfall?`<div class="warn">生活费仍有 ${money(p.shortfall)} 缺口，请调整预算或手动调整用途。</div>`:'')+'<p><small>仅分配已有且尚未安排用途的资金，不动用已存储蓄。若需修改建议，请取消后使用“手动调整资金用途”。</small></p>',p.state)}catch(e){modal('需要先调整',`<p>${esc(e.message)}</p>`,()=>{$('#modal').close();actions.adjust()})}},
check(){modal('每周核对余额',state.accounts.map((a,i)=>field('a'+i,esc(a.name)+'实际余额（元）',a.balance/100)).join('')+'<p class="muted">先补录遗漏收入。账户间转账请同时更新两边余额，不计为消费。</p><label>差额说明<input name="note" placeholder="例如：本周消费，或余额录入纠正" required></label>',f=>{const n=reconcile(state,state.accounts.map((a,i)=>cents(f.get('a'+i))));n.checked=date();n.lastCheck={note:f.get('note'),delta:total(n)-total(state)};preview('核对差额',`<p>总余额变化：${money(total(n)-total(state))}</p><p>${esc(f.get('note'))}</p><p>自由支配金额减少 ${money(state.free-n.free)}，储蓄和备用金保持不变。</p>${available(n)<0?`<div class="warn">仍有 ${money(-available(n))} 待调整。确认后请手动调整生活费或其他用途，恢复与实际余额一致。</div>`:'<p>用途记录与实际余额相符；新增差额暂不自动归类为收入。</p>'}`,n)})},
adjust(){modal('手动调整资金用途',`<p>可安排资金合计 ${money(total(state))}。用途调整不改变账户余额。</p>`+field('living','生活费预留',state.living/100)+field('reserve','备用金',state.reserve/100)+field('free','自由支配',state.free/100)+field('growth','未来增长储备',state.growth/100)+state.goals.map((g,i)=>field('g'+i,esc(g.name)+'已存金额',g.saved/100)).join(''),f=>{const n=structuredClone(state);for(const k of ['living','reserve','free','growth'])n[k]=cents(f.get(k));n.goals.forEach((g,i)=>{g.saved=cents(f.get('g'+i));if(g.saved>g.target)throw Error('目标已存金额不能超过目标金额')});if(available(n)<0)throw Error('用途总额超过实际资金，请减少分配');preview('确认用途调整',`<p>储蓄余额：${money(saved(state))} → ${money(saved(n))}</p><p>尚未分配：${money(available(n))}</p>`+n.goals.map((g,i)=>`<div class="row"><span>${esc(g.name)}</span><span>${money(state.goals[i].saved)} → ${money(g.saved)}</span></div>`).join(''),n)})},
bill(){modal('固定支出',state.bills.map((b,i)=>`<div class="row"><span>${esc(b.name)} · 每月 ${b.day} 日 · ${money(b.amount)}</span><button type="button" class="secondary" data-remove="${i}">删除</button></div>`).join('')+field('name','新增支出名称','','text')+field('amount','每月金额')+field('day','每月支付日',1,'number','max="31" step="1"')+'<small>此处是预算，不自动扣款。支付后在余额核对中确认消费并调整生活费预留。</small>',f=>{const n=structuredClone(state);n.bills.push({name:f.get('name').trim(),amount:cents(f.get('amount')),day:day(f.get('day'))});commit(n)});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const n=structuredClone(state);n.bills.splice(Number(b.dataset.remove),1);preview('删除固定支出预算','<p>只删除未来预算，不改变账户余额和已预留金额。</p>',n)})}
};render();

